import glob, os
lists = set()
for f in glob.glob('/var/lib/dpkg/info/*.list'):
    try:
        for line in open(f):
            p = line.rstrip('\n')
            if p.startswith(('/etc/systemd/system/','/usr/lib/systemd/system/','/run/systemd/system/')):
                lists.add(p)
    except Exception: pass
for d in ('/etc/systemd/system','/usr/lib/systemd/system','/run/systemd/system'):
    for root, dirs, files in os.walk(d):
        for fn in files:
            p = os.path.join(root, fn)
            if os.path.islink(p): continue
            if not os.path.isfile(p): continue
            if p not in lists:
                print('NOT-IN-DPKG:', p)
