cd /app && python3 << 'EOF'
import base64, string
text = ''
raw = base64.b64decode(text)

def rot13(b):
    out = bytearray()
    for c in b:
        if 65 <= c <= 90: out.append((c-65+13)%26+65)
        elif 97 <= c <= 122: out.append((c-97+13)%26+97)
        else: out.append(c)
    return bytes(out)

b64 = set(string.ascii_letters + string.digits + '+/=')
best = []
for k in range(256):
    xored = bytes(c ^ k for c in raw)
    r = rot13(xored)
    score = sum(1 for c in r if c in b64)
    best.append((score, k))
best.sort(reverse=True)
for score, k in best[:10]:
    print(score, k, rot13(bytes(c^k for c in raw))[:60])
# also try: xor then check ascii printable before rot13
best2 = []
for k in range(256):
    xored = bytes(c ^ k for c in raw)
    score = sum(1 for c in xored if 32 <= c < 127)
    best2.append((score, k))
best2.sort(reverse=True)
print('printable-ascii best:', best2[:5])
for score, k in best2[:3]:
    print(k, bytes(c^k for c in raw)[:60])
EOF

